parsed = urllib.parse.urlparse(raw_url)
query = urllib.parse.parse_qs(parsed.query)

print("=== URL ANALYSIS ===")
print("Base Path:", parsed.path)
print("\nQuery Parameters:")
for k, v in query.items():
    if k == "f_C":
        comp_ids = v[0].split(",")
        print(f"  {k}: {len(comp_ids)} company IDs filtered! First 10: {comp_ids[:10]}")
    else:
        print(f"  {k}: {v[0] if len(v) == 1 else v}")

# Let's inspect the currentJobId specifically
job_id = query.get("currentJobId", [""])[0]
print(f"\nTarget Job ID: {job_id}")

job_url = f"https://www.linkedin.com/jobs-guest/jobs/api/jobPosting/{job_id}"
print(f"Testing public guest API endpoint: {job_url}")

req = urllib.request.Request(
    job_url,
    headers={
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8"
    }
)

try:
    with urllib.request.urlopen(req, timeout=10) as resp:
        content = resp.read().decode("utf-8", errors="ignore")
        print(f"Response Code: {resp.status}, Content Length: {len(content)}")
        
        # Extract title
        m_title = re.search(r"<h2[^>]*class=\"[^\"]*topcard__title[^\"]*\"[^>]*>(.*?)</h2>", content, re.DOTALL)
        if not m_title:
            m_title = re.search(r"<title>(.*?)</title>", content, re.DOTALL)
            
        m_company = re.search(r"<a[^>]*class=\"[^\"]*topcard__org-name-link[^\"]*\"[^>]*>(.*?)</a>", content, re.DOTALL)
        if not m_company:
            m_company = re.search(r"<span[^>]*class=\"[^\"]*topcard__flavor[^\"]*\"[^>]*>(.*?)</span>", content, re.DOTALL)
            
        m_location = re.search(r"<span[^>]*class=\"[^\"]*topcard__flavor--bullet[^\"]*\"[^>]*>(.*?)</span>", content, re.DOTALL)
        
        print("\nExtracted Job Data:")
        print("  Title:", m_title.group(1).strip() if m_title else "Unknown")
        print("  Company:", m_company.group(1).strip() if m_company else "Unknown")
        print("  Location:", m_location.group(1).strip() if m_location else "Unknown")
        
        # Snippet of description
        desc_clean = re.sub(r"<[^>]+>", " ", content)
        desc_clean = re.sub(r"\s+", " ", desc_clean).strip()
        print("  Snippet:", desc_clean[:300])
except Exception as e:
    print(f"Guest API fetch error: {e}")
